// src/baseComponents/InputField/index.tsx
import type React from "react";

import { forwardRef, type JSX } from "react";

import { joinClasses } from "~utils/joinClasses";

import typography from "../../styles/typography.module.css";
import { BaseField } from "../BaseField";
import styles from "../BaseField/BaseField.module.css";

export interface IInputFieldProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "onChange" | "value"
> {
  id: string;
  labelText?: string;
  value?: string;
  readOnly?: boolean;
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  onKeyDown?: (event: React.KeyboardEvent<HTMLInputElement>) => void;
  onEnterPress?: (event: React.KeyboardEvent<HTMLInputElement>) => void;
  isClearable?: boolean;
  inputLeftIcon?: JSX.Element;
  isFocused?: boolean;
  setIsFocused?: (value: boolean) => void;
  hintText?: string;
  isError?: boolean;
  className?: string;
  style?: React.CSSProperties;
  variant?: "default" | "code";
}

export const InputField = forwardRef<HTMLInputElement, IInputFieldProps>(
  (props, ref) => {
    const {
      id,
      labelText,
      value,
      readOnly,
      onChange,
      onKeyDown,
      variant = "default",
      isFocused,
      setIsFocused,
      isClearable,
      inputLeftIcon,
      isError,
      hintText,
      ...htmlProps
    } = props;

    const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
      onKeyDown?.(event);
      if (event.key === "Enter") {
        props.onEnterPress?.(event);
      }
    };

    return (
      <BaseField<HTMLInputElement>
        {...props}
        className={joinClasses(
          variant === "code" && styles.codeField,
          htmlProps.className,
        )}
        onChange={onChange}
        value={value}
        isFocused={isFocused}
        setIsFocused={setIsFocused}
        isClearable={isClearable}
        inputLeftIcon={inputLeftIcon}
        isError={isError}
        hintText={hintText}
      >
        {({ handleFocus, handleBlur, isShowPlaceholder, handleChange }) => (
          <input
            data-testid="InputField_INPUT"
            ref={ref}
            {...htmlProps}
            id={id}
            value={value}
            readOnly={readOnly}
            placeholder={isShowPlaceholder ? labelText : ""}
            onKeyDown={handleKeyDown}
            onFocus={handleFocus}
            onBlur={handleBlur}
            onChange={(e) => {
              handleChange(e);
            }}
            className={joinClasses(
              styles.input,
              variant === "code" && styles.code,
              variant === "code" && typography.heading3,
              htmlProps.className,
            )}
          />
        )}
      </BaseField>
    );
  },
);
